import React, { useState } from 'react';
import { motion } from 'framer-motion';
import DashboardLayout from '../components/dashboard/DashboardLayout';

const SettingsPage = () => {
  const [settings, setSettings] = useState({
    emailProcessingEnabled: true,
    processingFrequency: '15',
    batchSize: '50',
    autoRespond: true,
    notificationsEnabled: true,
    emailAddress: 'user@example.com',
    name: 'John Doe',
  });

  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      setLoading(true);
      setError(null);
      setSuccess(false);

      // In a real app, you would send settings to API
      // await emailService.updateSettings(settings);

      // Simulate API delay
      await new Promise(resolve => setTimeout(resolve, 1000));

      setSuccess(true);
      setLoading(false);
    } catch (err) {
      console.error('Error updating settings:', err);
      setError('Failed to update settings. Please try again.');
      setLoading(false);
    }
  };

  return (
    <DashboardLayout>
      <div style={{ maxWidth: '800px', margin: '0 auto' }}>
        <header style={{ marginBottom: '24px' }}>
          <h1 style={{ 
            fontSize: '24px', 
            fontWeight: '700', 
            color: 'var(--text-color)',
            marginBottom: '8px'
          }}>
            Settings
          </h1>
          <p style={{ fontSize: '15px', color: 'var(--body-color)' }}>
            Configure your email processing preferences
          </p>
        </header>

        {success && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              backgroundColor: 'rgba(16, 185, 129, 0.1)',
              borderRadius: '6px',
              padding: '12px 16px',
              marginBottom: '24px',
              color: '#10B981',
              fontSize: '14px',
            }}
          >
            Settings saved successfully!
          </motion.div>
        )}

        {error && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.3 }}
            style={{
              backgroundColor: 'rgba(239, 68, 68, 0.1)',
              borderRadius: '6px',
              padding: '12px 16px',
